#include "sweep_io.h"
#include <stdio.h>
#include <string.h>

/* Generated by STM32CubeMX, usually in main.c */
extern ADC_HandleTypeDef hadc1;
extern DAC_HandleTypeDef hdac1;
extern UART_HandleTypeDef huart2;

volatile float vgs_set_live = 0.0f;
volatile float vgs_measured_live = 0.0f;
volatile float vsupply_measured_live = 0.0f;
volatile float vdrain_measured_live = 0.0f;
volatile float resistor_drop_live = 0.0f;
volatile float id_uA_live = 0.0f;
volatile uint32_t sample_id_live = 0U;
volatile uint32_t sweep_id_live = 0U;
volatile uint32_t point_index_live = 0U;
volatile uint32_t time_ms_live = 0U;
volatile uint32_t sweeps_completed_live = 0U;
volatile uint32_t measurement_done_live = 0U;
volatile uint32_t sweep_status_live = 0U;

volatile float vgs_set_points[SWEEP_POINTS] = {0};
volatile float vgs_measured[SWEEP_POINTS] = {0};
volatile float vsupply_measured[SWEEP_POINTS] = {0};
volatile float vdrain_measured[SWEEP_POINTS] = {0};
volatile float id_uA[SWEEP_POINTS] = {0};

void Sweep_Fatal(uint32_t status)
{
    sweep_status_live = status;
    Error_Handler();
    while (1) { }
}

static uint32_t Sweep_DacCode(float volts)
{
    if (volts < 0.0f) volts = 0.0f;
    if (volts > ADC_VREF_ASSUMED_V) volts = ADC_VREF_ASSUMED_V;
    return (uint32_t)(volts / ADC_VREF_ASSUMED_V * 4095.0f + 0.5f);
}

void Sweep_SetOutput(uint32_t channel, float volts)
{
    if (HAL_DAC_SetValue(&hdac1, channel, DAC_ALIGN_12B_R, Sweep_DacCode(volts)) != HAL_OK)
        Sweep_Fatal(5U);
}

static HAL_StatusTypeDef Sweep_ReadADC(uint32_t channel, float *voltage)
{
    ADC_ChannelConfTypeDef cfg = {0};
    uint32_t total = 0U;
    cfg.Channel = channel;
    cfg.Rank = ADC_REGULAR_RANK_1;
    cfg.SamplingTime = ADC_SAMPLETIME_247CYCLES_5;
    cfg.SingleDiff = ADC_SINGLE_ENDED;
    cfg.OffsetNumber = ADC_OFFSET_NONE;
    cfg.Offset = 0;

    if (HAL_ADC_ConfigChannel(&hadc1, &cfg) != HAL_OK) return HAL_ERROR;
    for (uint32_t n = 0U; n < ADC_AVERAGE_COUNT; n++)
    {
        if (HAL_ADC_Start(&hadc1) != HAL_OK) return HAL_ERROR;
        HAL_StatusTypeDef status = HAL_ADC_PollForConversion(&hadc1, 100U);
        if (status != HAL_OK)
        {
            (void)HAL_ADC_Stop(&hadc1);
            return status;
        }
        total += HAL_ADC_GetValue(&hadc1);
        if (HAL_ADC_Stop(&hadc1) != HAL_OK) return HAL_ERROR;
    }
    *voltage = ((float)total / (float)ADC_AVERAGE_COUNT)
             * ADC_VREF_ASSUMED_V / 4095.0f;
    return HAL_OK;
}

SweepSample Sweep_ReadSample(void)
{
    SweepSample sample;
    if (Sweep_ReadADC(ADC_CHANNEL_6, &sample.supply_v) != HAL_OK) /* A1 / PA1 */
        Sweep_Fatal(2U);
    if (Sweep_ReadADC(ADC_CHANNEL_5, &sample.drain_v) != HAL_OK) /* A0 / PA0 */
        Sweep_Fatal(2U);
    if (Sweep_ReadADC(ADC_CHANNEL_8, &sample.gate_v) != HAL_OK) /* A2 / PA3 */
        Sweep_Fatal(2U);
    return sample;
}

void Sweep_SendText(const char *text)
{
    size_t len = strlen(text);
    if (len > UINT16_MAX) Sweep_Fatal(4U);
    if (HAL_UART_Transmit(&huart2, (uint8_t *)text, (uint16_t)len, 1000U) != HAL_OK)
        Sweep_Fatal(3U);
}

void Sweep_StartHardware(float supply_v)
{
    if (HAL_ADCEx_Calibration_Start(&hadc1, ADC_SINGLE_ENDED) != HAL_OK)
        Sweep_Fatal(2U);
    if (HAL_DAC_Start(&hdac1, DAC_CHANNEL_1) != HAL_OK)
        Sweep_Fatal(5U);
    if (HAL_DAC_Start(&hdac1, DAC_CHANNEL_2) != HAL_OK)
        Sweep_Fatal(5U);
    Sweep_SetOutput(DAC_CHANNEL_1, 0.0f);
    Sweep_SetOutput(DAC_CHANNEL_2, supply_v);
    HAL_Delay(100U);
}

void Sweep_Init(void)
{
    Sweep_StartHardware(VSUPPLY_DAC_SET_V);
    Sweep_SendText("VGS_Set,VGS_Measured,VSupply,VDrain,ID_uA,time_ms,sample_id,sweep_id,point_index\r\n");
}

void Sweep_RunAllSets(void)
{
    uint32_t sample_id = 0U;
    for (uint32_t set = 0U; set < SWEEP_SETS; ++set)
    {
        uint32_t sweep_id = set + 1U; /* 1-based sweep number */
        for (uint32_t point = 0U; point < SWEEP_POINTS; ++point)
        {
            float vgs_set = VGS_START_V
                 + (VGS_END_V - VGS_START_V) * (float)point / (float)(SWEEP_POINTS - 1U);
            char csv_line[192];

            Sweep_SetOutput(DAC_CHANNEL_1, vgs_set);
            HAL_Delay(DAC_SETTLE_MS);

            const SweepSample sample = Sweep_ReadSample();
            const float supply_v = sample.supply_v;
            const float drain_v = sample.drain_v;
            const float gate_v = sample.gate_v;

            float drop_v = supply_v - drain_v;
            float current_uA = drop_v * (1000000.0f / DRAIN_RESISTOR_OHM);
            uint32_t measured_at_ms = HAL_GetTick();
            sweep_status_live = (drop_v < -0.020f) ? 1U : 0U;

            vgs_set_live = vgs_set;
            vgs_measured_live = gate_v;
            vsupply_measured_live = supply_v;
            vdrain_measured_live = drain_v;
            resistor_drop_live = drop_v;
            id_uA_live = current_uA;
            sample_id_live = sample_id;
            sweep_id_live = sweep_id;
            point_index_live = point;
            time_ms_live = measured_at_ms;
            vgs_set_points[point] = vgs_set;
            vgs_measured[point] = gate_v;
            vsupply_measured[point] = supply_v;
            vdrain_measured[point] = drain_v;
            id_uA[point] = current_uA;

            /* Float snprintf requires linker flag: -u _printf_float */
            int n = snprintf(csv_line, sizeof(csv_line),
                             "%.6f,%.5f,%.5f,%.5f,%.4f,%lu,%lu,%lu,%lu\r\n",
                             (double)vgs_set, (double)gate_v,
                             (double)supply_v, (double)drain_v,
                             (double)current_uA,
                             (unsigned long)measured_at_ms,
                             (unsigned long)sample_id,
                             (unsigned long)sweep_id,
                             (unsigned long)point);
            if (n < 0 || (size_t)n >= sizeof(csv_line)) Sweep_Fatal(4U);
            Sweep_SendText(csv_line);
            ++sample_id;
            HAL_Delay(POINT_PAUSE_MS);
        }

        sweeps_completed_live = sweep_id;
        /* Reset gate between full sweeps (DAC buffered output may not reach true 0 V). */
        Sweep_SetOutput(DAC_CHANNEL_1, 0.0f);
        if (set + 1U < SWEEP_SETS) HAL_Delay(SWEEP_PAUSE_MS);
    }
    measurement_done_live = 1U;
}
